import { FormEvent, useState } from "react";
import { buildOverlapInsights } from "./shared";
import type { CandidateProfile, WorkspaceState } from "../types";
import type { ChatMessage, InterviewConfig } from "./shared";
import { makeId } from "./shared";

export function JdFlowView({
