function JdDetailModal({ workspace, onClose, onConfigure }: { workspace: WorkspaceState; onClose: () => void; onConfigure: () => void }) {
  const responsibilities = workspace.job.responsibilities.length ? workspace.job.responsibilities : workspace.job.keywords.slice(0, 6).map((item) => `围绕 ${item} 展开岗位职责`);
  const requirements = [...workspace.job.hardSkills, ...workspace.job.softSkills].slice(0, 8).map((item) => `具备 ${item} 相关能力，并能用真实经历证明`);
  const dimensions = ["岗位理解与动机", "项目深挖与个人贡献", "数据/工具能力", "表达结构与抗压追问", "业务理解与复盘能力"];
  return <div className="modal-backdrop" role="presentation" onClick={onClose}><section className="flow-modal jd-detail-modal" role="dialog" aria-modal="true" aria-label="JD 详情" onClick={(event) => event.stopPropagation()}><header><span>步骤 1/2 · JD 详情</span><button className="button text-button" onClick={onClose}>关闭</button></header><h2>{workspace.job.title}</h2><p>{workspace.job.company} · 匹配度 {workspace.matchReport.score}/100</p><div className="modal-divider" /><section><h3>岗位职责</h3><ul>{responsibilities.map((item) => <li key={item}>{item}</li>)}</ul></section><section><h3>任职要求</h3><ul>{(requirements.length ? requirements : workspace.matchReport.gaps.map((gap) => gap.description)).slice(0, 8).map((item) => <li key={item}>{item}</li>)}</ul></section><section><h3>评估维度</h3><ul>{dimensions.map((item) => <li key={item}>{item}</li>)}</ul></section><footer><button className="button secondary" onClick={onClose}>关闭</button><button className="button primary" onClick={onConfigure}>配置面试</button></footer></section></div>;
}

function InterviewConfigModal({ config, onChange, onClose, onBack, onStart }: { config: InterviewConfig; onChange: (config: InterviewConfig) => void; onClose: () => void; onBack: () => void; onStart: () => void }) {
  const setValue = <Key extends keyof InterviewConfig>(key: Key, value: InterviewConfig[Key]) => onChange({ ...config, [key]: value });
  return <div className="modal-backdrop" role="presentation" onClick={onClose}><section className="flow-modal config-modal" role="dialog" aria-modal="true" aria-label="配置面试" onClick={(event) => event.stopPropagation()}><header><span>步骤 2/2 · 配置面试</span><button className="button text-button" onClick={onClose}>关闭</button></header><h2>模拟面试配置</h2><ConfigOptionGroup title="面试阶段" options={["HR", "上级", "CEO", "CTO", "业务负责人"]} value={config.stage} onSelect={(value) => setValue("stage", value as InterviewConfig["stage"])} /><ConfigOptionGroup title="面试难度" options={["正常", "压力面", "地狱面"]} value={config.difficulty} onSelect={(value) => setValue("difficulty", value as InterviewConfig["difficulty"])} /><ConfigOptionGroup title="面试官性别" options={["女", "男"]} value={config.interviewerGender} onSelect={(value) => setValue("interviewerGender", value as InterviewConfig["interviewerGender"])} /><section><h3>提交方式</h3><div className="config-choice-grid"><button className={config.submitMode === "manual" ? "config-choice active" : "config-choice"} onClick={() => setValue("submitMode", "manual")} type="button"><strong>手动确认（推荐）</strong><span>说完后点击“我说完了”，中途停顿不会被打断</span></button><button className={config.submitMode === "auto" ? "config-choice active" : "config-choice"} onClick={() => setValue("submitMode", "auto")} type="button"><strong>自动判断</strong><span>停顿约 1.5 秒后自动接话，适合连续练习</span></button></div></section><footer><button className="button secondary" onClick={onBack}>返回详情</button><button className="button primary" onClick={onStart}>开始面试</button></footer></section></div>;
}

function ConfigOptionGroup({ title, options, value, onSelect }: { title: string; options: string[]; value: string; onSelect: (value: string) => void }) {
  return <section><h3>{title}</h3><div className="config-option-grid">{options.map((option) => <button key={option} type="button" className={value === option ? "config-option active" : "config-option"} onClick={() => onSelect(option)}>{option}</button>)}</div></section>;
}

