            <h2>确认当前 JD</h2>
            <form onSubmit={(event) => {
              event.preventDefault();
              const form = event.currentTarget;
              const text = new FormData(form).get("jobText");
              if (typeof text === "string" && text.trim()) onSubmitJd(text.trim());
              setContextOpen(false);
            }}>
              <textarea className="modal-textarea" name="jobText" defaultValue={workspace.jobText} aria-label="JD 文本" />
              <footer><button className="button secondary" type="button" onClick={() => setContextOpen(false)}>取消</button><button className="button primary">保存 JD</button></footer>
