export function LiveAssistantView({
  profile,
  position,
  onSaveRecord,
  onSaveQuestion,
  compact = false,
}: {
  profile: CandidateProfile;
  position: Position;
  onSaveRecord: (payload: { mode: "live"; title: string; transcript: MockMessage[]; cueCards: AnswerCueCard[]; speechMetrics?: ReturnType<typeof analyzeSpeech>[] }) => void;
  onSaveQuestion: (card: AnswerCueCard) => void;
  compact?: boolean;
}) {
  const [recognizedDraft, setRecognizedDraft] = useState<RecognizedDraft>({ interimText: "", finalText: "", editableText: "", lastFinalAt: 0 });
  const [captureState, setCaptureState] = useState<SpeechCaptureState>("idle");
  const [submitMode, setSubmitMode] = useState<RealtimeSubmitMode>("manual");
  const [lastGeneratedAt, setLastGeneratedAt] = useState(0);
  const [transcript, setTranscript] = useState<MockMessage[]>([]);
  const [cueCards, setCueCards] = useState<AnswerCueCard[]>([]);
  const [cueMeta, setCueMeta] = useState<AiRunMeta | null>(null);
  const [backendHint, setBackendHint] = useState("");
  const [listening, setListening] = useState(false);
  const [durationSec, setDurationSec] = useState(0);
  const [startedAt, setStartedAt] = useState<number | null>(null);
  const [voiceError, setVoiceError] = useState("");
  const dictationRef = useRef<DictationHandle | null>(null);
  const sttSupported = isSpeechRecognitionSupported();
  useEffect(() => () => dictationRef.current?.stop(), []);

  const generate = useCallback((sourceText = recognizedDraft.editableText) => {
    if (!sourceText.trim()) return;
    const question = sourceText.trim();
    setLastGeneratedAt(Date.now());
    const card = generateCueCard(question, profile, position, position.questions, "live");
    setCueCards((current) => [card, ...current]);
    setTranscript((current) => [...current, { role: "interviewer", text: question }]);
    setCaptureState("generating");
    setCueMeta({ backendStatus: "fallback", fallbackReason: "正在连接后端模型，先展示本地练习题词卡。", evidenceTrace: [], latencyMs: 0 });
    setBackendHint("本地练习模式已先生成题词卡，正在尝试后端模型");
    void streamCueCardFromServer({ questionText: question, positionId: position.id, source: "live", enableSearch: true })
      .then((result) => {
        setCueCards((current) => [result.card, ...current.filter((item) => item.id !== card.id)]);
        setCueMeta({
          backendStatus: result.backendStatus,
          fallbackReason: result.fallbackReason,
          evidenceTrace: result.evidenceTrace,
          latencyMs: result.latencyMs,
        });
        setBackendHint(result.backendStatus === "success" ? "模型生成 · 已使用服务端编排" : `模型失败 · 本地练习：${result.fallbackReason}`);
      })
      .catch(() => {
        setCueMeta({ backendStatus: "fallback", fallbackReason: "后端未连接，当前使用本地规则题词卡。", evidenceTrace: [], latencyMs: 0 });
        setBackendHint("后端未连接 · 本地练习模式");
      })
      .finally(() => setCaptureState("ready"));
  }, [position, profile, recognizedDraft.editableText]);

  useEffect(() => {
    if (submitMode !== "auto") return;
    if (!recognizedDraft.lastFinalAt || recognizedDraft.lastFinalAt <= lastGeneratedAt) return;
    const timer = window.setTimeout(() => {
      if (recognizedDraft.editableText.trim() && recognizedDraft.lastFinalAt > lastGeneratedAt) generate(recognizedDraft.editableText);
    }, 450);
    return () => window.clearTimeout(timer);
  }, [generate, lastGeneratedAt, recognizedDraft.editableText, recognizedDraft.lastFinalAt, submitMode]);

  const toggleDictation = () => {
    if (listening) {
      setCaptureState("finalizing");
      dictationRef.current?.stop();
      if (startedAt) setDurationSec((current) => current + Math.max(1, Math.round((Date.now() - startedAt) / 1000)));
      setStartedAt(null);
      return;
    }
    if (!sttSupported) {
      setVoiceError("当前浏览器不支持语音识别，请直接输入面试官问题。");
      setCaptureState("error");
      return;
    }
    setVoiceError("");
    setStartedAt(Date.now());
    setListening(true);
    setCaptureState("listening");
    dictationRef.current = startDictation({
      lang: "zh-CN",
      onText: (text, isFinal) => {
        setRecognizedDraft((current) => {
          if (!isFinal) return { ...current, interimText: text };
          const finalText = [current.finalText, text].filter(Boolean).join(current.finalText ? " " : "").trim();
          return { interimText: "", finalText, editableText: finalText, lastFinalAt: Date.now() };
        });
        if (isFinal) setCaptureState("ready");
      },
      onError: (message) => {
        setVoiceError(message);
        setListening(false);
        setStartedAt(null);
        setCaptureState("error");
      },
      onEnd: () => {
        setListening(false);
        setStartedAt(null);
        setCaptureState((current) => (current === "error" ? "error" : "ready"));
      },
    });
  };

  const clearDraft = () => {
    setRecognizedDraft({ interimText: "", finalText: "", editableText: "", lastFinalAt: 0 });
    setCueMeta(null);
    setBackendHint("");
    setCaptureState("idle");
  };

  const save = () => {
    const speechMetrics = transcript.length > 0 ? [analyzeSpeech(transcript.map((item) => item.text).join(" "), Math.max(durationSec, 30))] : [];
    onSaveRecord({ mode: "live", title: `${position.title} 实时助手`, transcript, cueCards, speechMetrics });
  };

  return (
    <section className={compact ? "live-assistant-core" : "page-section"}>
      {!compact && <EditorHeader icon={Mic} title="实时助手" description="主动开启麦克风或输入面试官问题，系统基于 JD、简历和问题库生成题词卡。" action={<button className="button primary" onClick={save} disabled={cueCards.length === 0}>保存为面试记录</button>} />}
      <div className="live-grid">
        <Panel title="听到的问题">
          <div className="mode-switch interactive" aria-label="生成方式">
            <button type="button" className={submitMode === "manual" ? "active" : ""} onClick={() => setSubmitMode("manual")}>手动确认</button>
            <button type="button" className={submitMode === "auto" ? "active" : ""} onClick={() => setSubmitMode("auto")}>自动生成</button>
          </div>
          <button className={listening ? "button danger wide" : "button primary wide"} onClick={toggleDictation}><Mic size={17} />{listening ? "停止听取" : "听面试官问题"}</button>
          {voiceError && <div className="inline-message error">{voiceError}</div>}
          {!sttSupported && <p className="form-hint">当前浏览器不支持语音识别，已降级为文字输入。</p>}
          <div className="recognized-box">
            <span>已识别文本 · {captureState === "listening" ? "正在听" : captureState === "generating" ? "生成中" : "可编辑"}</span>
            {recognizedDraft.interimText && <p>临时识别：{recognizedDraft.interimText}</p>}
          </div>
          <textarea
            value={recognizedDraft.editableText}
            onChange={(event) => setRecognizedDraft((current) => ({ ...current, editableText: event.target.value }))}
            aria-label="实时问题输入"
            placeholder="语音停止后文本会保留在这里；也可以直接输入或编辑面试官问题..."
          />
          <div className="assistant-actions">
            <button className="button secondary" onClick={clearDraft} disabled={!recognizedDraft.editableText && !recognizedDraft.interimText}>清空/重录</button>
            <button className="button primary" onClick={() => generate()} disabled={!recognizedDraft.editableText.trim() || captureState === "generating"}>{captureState === "generating" ? "生成中..." : "生成题词卡"}<ArrowRight size={16} /></button>
          </div>
          {backendHint && <div className="inline-message success">{backendHint}</div>}
        </Panel>
        <CueCardPanel card={cueCards[0]} meta={cueMeta} onSaveQuestion={onSaveQuestion} />
        {!compact && <Panel title="上下文命中"><ContextStack profile={profile} position={position} /></Panel>}
        {compact && <button className="button primary live-save-button" onClick={save} disabled={cueCards.length === 0}>保存为面试记录</button>}
      </div>
    </section>
  );
}

export function InterviewRoomView({ workspace, profile, position, onSaveRecord, onSaveQuestion, config }: { workspace: WorkspaceState; profile: CandidateProfile; position: Position; onSaveRecord: (payload: { mode: "mock"; title: string; transcript: MockMessage[]; cueCards: AnswerCueCard[]; turn?: MockTurn; speechMetrics?: ReturnType<typeof analyzeSpeech>[] }) => void; onSaveQuestion: (card: AnswerCueCard) => void; config: InterviewConfig }) {
  const questionPlan = useMemo(() => {
    const priority = workspace.questions.filter((question) => question.priority);
    const rest = workspace.questions.filter((question) => !question.priority);
    return [...priority, ...rest].slice(0, 8);
  }, [workspace.questions]);
  const [questionIndex, setQuestionIndex] = useState(0);
  const [answerDraft, setAnswerDraft] = useState<RecognizedDraft>({ interimText: "", finalText: "", editableText: "", lastFinalAt: 0 });
  const [transcript, setTranscript] = useState<MockMessage[]>([{ role: "interviewer", text: questionPlan[0]?.question ?? "请先介绍一下你和这个岗位最相关的一段经历。" }]);
  const [cueCards, setCueCards] = useState<AnswerCueCard[]>([]);
  const [cueMeta, setCueMeta] = useState<AiRunMeta | null>(null);
  const [backendHint, setBackendHint] = useState("");
  const [modelStatus, setModelStatus] = useState<"checking" | "model" | "local">("checking");
  const [questionSource, setQuestionSource] = useState("题库排序");
  const [sessionId, setSessionId] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [lastSubmittedAt, setLastSubmittedAt] = useState(0);
  const [durationSec, setDurationSec] = useState(0);
  const startedAtRef = useRef<number | null>(null);
  const [listening, setListening] = useState(false);
  const [paused, setPaused] = useState(false);
  const [voiceError, setVoiceError] = useState("");
  const dictationRef = useRef<DictationHandle | null>(null);
  const sttSupported = isSpeechRecognitionSupported();
  const ttsSupported = isSpeechSynthesisSupported();
  const currentQuestion = questionPlan[questionIndex] ?? workspace.questions[0];
  const currentAnswer = workspace.answers.find((item) => item.questionId === currentQuestion?.id);
  const currentPrompt = transcript.filter((message) => message.role === "interviewer").at(-1)?.text ?? currentQuestion?.question ?? "";
  const answer = answerDraft.editableText;
  const answeredCount = transcript.filter((message) => message.role === "candidate").length;
  const offTopicCount = Math.max(0, Math.min(3, Math.round((100 - workspace.matchReport.score) / 18) - answeredCount));
  const favorability = Math.max(50, Math.min(96, workspace.matchReport.score + answeredCount * 4 - offTopicCount * 5));

  useEffect(() => () => {
    dictationRef.current?.stop();
    cancelSpeak();
  }, []);

  useEffect(() => {
    let active = true;
    void createMockSessionOnServer(position.id)
      .then((result) => {
        if (!active) return;
        setSessionId(result.sessionId);
        setTranscript([{ role: "interviewer", text: result.question }]);
        setModelStatus(result.backendStatus === "success" ? "model" : "local");
        setQuestionSource(result.questionSource ?? (result.backendStatus === "success" ? "model" : "local"));
        setBackendHint(result.backendStatus === "success" ? "模型面试官已接入" : `DeepSeek 未配置或不可用，当前为本地练习模式${result.meta?.fallbackReason ? `：${result.meta.fallbackReason}` : ""}`);
      })
      .catch(() => {
        if (!active) return;
        setModelStatus("local");
        setBackendHint("后端未连接，当前为本地练习模式");
      });
    return () => {
      active = false;
    };
  }, [position.id]);

  useEffect(() => {
    startedAtRef.current ??= Date.now();
    const timer = window.setInterval(() => {
      if (!paused && startedAtRef.current) setDurationSec(Math.max(0, Math.round((Date.now() - startedAtRef.current) / 1000)));
    }, 1000);
    return () => window.clearInterval(timer);
  }, [paused]);

  const toggleDictation = () => {
    if (listening) {
      dictationRef.current?.stop();
      return;
    }
    if (!sttSupported) {
      setVoiceError("当前浏览器不支持语音识别，可以直接输入回答。");
      return;
    }
    setVoiceError("");
    setListening(true);
    dictationRef.current = startDictation({
      lang: "zh-CN",
      onText: (text, isFinal) => {
        setAnswerDraft((current) => {
          if (!isFinal) return { ...current, interimText: text, editableText: current.finalText || text };
          const finalText = [current.finalText, text].filter(Boolean).join(current.finalText ? " " : "").trim();
          return { interimText: "", finalText, editableText: finalText, lastFinalAt: Date.now() };
        });
      },
      onError: (message) => {
        setVoiceError(message);
        setListening(false);
      },
      onEnd: () => setListening(false),
    });
  };

  const showCueCard = () => {
    if (!currentPrompt.trim()) return;
    const card = generateCueCard(currentPrompt, profile, position, workspace.questions, "mock");
    setCueCards((current) => [card, ...current]);
    setCueMeta({ backendStatus: "fallback", fallbackReason: "正在连接后端模型，先展示本地练习题词卡。", evidenceTrace: [], latencyMs: 0 });
    setBackendHint("本地规则已先生成题词卡");
    void streamCueCardFromServer({ questionText: currentPrompt, positionId: position.id, source: "mock", enableSearch: false })
      .then((result) => {
        setCueCards((current) => [result.card, ...current.filter((item) => item.id !== card.id)]);
        setCueMeta({
          backendStatus: result.backendStatus,
          fallbackReason: result.fallbackReason,
          evidenceTrace: result.evidenceTrace,
          latencyMs: result.latencyMs,
        });
        setBackendHint(result.backendStatus === "success" ? "模型生成 · 已使用服务端编排" : `模型失败 · 本地练习：${result.fallbackReason}`);
      })
      .catch(() => {
        setCueMeta({ backendStatus: "fallback", fallbackReason: "后端未连接，当前使用本地规则题词卡。", evidenceTrace: [], latencyMs: 0 });
        setBackendHint("后端未连接 · 本地练习模式");
      });
  };

  const submitAnswer = useCallback(() => {
    if (!answer.trim() || !currentQuestion || submitting) return;
    setSubmitting(true);
    setLastSubmittedAt(Date.now());
    const history: MockMessage[] = [...transcript, { role: "candidate", text: answer.trim() }];
    setTranscript(history);
    setAnswerDraft({ interimText: "", finalText: "", editableText: "", lastFinalAt: 0 });
    void answerMockSessionOnServer({ sessionId, positionId: position.id, questionId: currentQuestion.id, answer: answer.trim(), transcript: history })
      .then((result) => {
        const followUp = result.followUp || questionPlan[questionIndex + 1]?.question || generateFollowUpFromTranscript(history, profile, position);
        setTranscript([...history, { role: "interviewer", text: followUp }]);
        setModelStatus(result.backendStatus === "success" ? "model" : "local");
        setQuestionSource(result.backendStatus === "success" ? "model follow-up" : "local follow-up");
        setBackendHint(result.backendStatus === "success" ? "模型面试官已根据回答追问" : `DeepSeek 未配置或不可用，当前为本地练习模式${result.meta?.fallbackReason ? `：${result.meta.fallbackReason}` : ""}`);
      })
      .catch(() => {
        const followUp = questionPlan[questionIndex + 1]?.question ?? generateFollowUpFromTranscript(history, profile, position);
        setTranscript([...history, { role: "interviewer", text: followUp }]);
        setModelStatus("local");
        setBackendHint("后端未连接，当前为本地练习模式");
      })
      .finally(() => {
        setQuestionIndex((current) => Math.min(current + 1, questionPlan.length - 1));
        setSubmitting(false);
      });
  }, [answer, currentQuestion, position, profile, questionIndex, questionPlan, sessionId, submitting, transcript]);

  useEffect(() => {
    if (config.submitMode !== "auto") return;
    if (!answerDraft.lastFinalAt || answerDraft.lastFinalAt <= lastSubmittedAt) return;
    const timer = window.setTimeout(() => {
      if (answerDraft.editableText.trim()) submitAnswer();
    }, 900);
    return () => window.clearTimeout(timer);
  }, [answerDraft.editableText, answerDraft.lastFinalAt, config.submitMode, lastSubmittedAt, submitAnswer]);

  const finish = () => {
    const finalTranscript = answer.trim() ? [...transcript, { role: "candidate" as const, text: answer.trim() }] : transcript;
    const finalAnswer = answer.trim() || finalTranscript.filter((message) => message.role === "candidate").at(-1)?.text || "";
    const speechMetrics = analyzeSpeech(finalAnswer, Math.max(durationSec, Math.round(finalAnswer.length / 3), 20));
    const turn = currentQuestion ? evaluateMockTurn(currentQuestion, finalAnswer || "未完成回答", currentAnswer) : undefined;
    const fullTurn = turn ? { ...turn, transcript: finalTranscript, speechMetrics } : undefined;
    onSaveRecord({ mode: "mock", title: `${workspace.job.title} 模拟面试`, transcript: finalTranscript, cueCards, turn: fullTurn, speechMetrics: [speechMetrics] });
  };

  return (
    <section className="interview-room">
      <header className="room-topbar">
        <strong>{workspace.job.title}</strong>
        <span><Timer size={14} />{formatDuration(durationSec)}</span>
        <span className={listening ? "live-dot active" : "live-dot"}>{listening ? "识别中" : modelStatus === "model" ? "模型模式" : modelStatus === "checking" ? "连接中" : "本地练习模式"}</span>
        <span>题源 {questionSource}</span>
        <span>好感度 {favorability}</span>
        <span>跑题 {offTopicCount}/3</span>
        <button className="button secondary" onClick={finish}>结束面试</button>
      </header>
      <div className="room-grid">
        <main className="room-main">
          <section className="interviewer-panel">
            <div className="interviewer-avatar">面试官 · {config.stage} · {config.difficulty}</div>
            <div className="room-transcript">
              {transcript.map((message, index) => (
                <div key={`${message.role}-${index}`} className={`room-message ${message.role}`}>
                  <span>{message.role === "interviewer" ? "面试官" : "我"}</span>
                  <p>{message.text}</p>
                </div>
              ))}
              {answerDraft.interimText && <div className="room-message candidate draft"><span>临时识别</span><p>{answerDraft.interimText}</p></div>}
              {answer && <div className="room-message candidate draft"><span>我的草稿</span><p>{answer}</p></div>}
            </div>
          </section>
          <section className="answer-console">
            <textarea value={answer} onChange={(event) => setAnswerDraft((current) => ({ ...current, editableText: event.target.value }))} aria-label="模拟面试回答" placeholder="语音回答会实时转写并保留在这里；也可以直接输入你的回答..." />
            {voiceError && <div className="inline-message error">{voiceError}</div>}
            {!sttSupported && <p className="form-hint">当前浏览器不支持语音识别，已降级为文字输入。</p>}
          </section>
        </main>
        <aside className="cue-side">
          <CueCardPanel card={cueCards[0]} meta={cueMeta} onSaveQuestion={onSaveQuestion} />
          <details className="context-drawer">
            <summary>问题库与候选素材</summary>
            <div className="compact-question-list">{questionPlan.slice(0, 4).map((question) => <article key={question.id}><span>{question.category}</span><p>{question.question}</p></article>)}</div>
            <ul className="action-list">{currentAnswer && <li><Check size={16} /><span>{currentAnswer.concise}</span></li>}{workspace.resume.evidence.slice(0, 2).map((item) => <li key={item.id}><Check size={16} /><span>{item.title}：{item.impact}</span></li>)}</ul>
          </details>
        </aside>
      </div>
      <footer className="voice-dock">
        <div className="mode-switch" aria-label="提交方式"><span className={config.submitMode === "manual" ? "active" : ""}>手动</span><span className={config.submitMode === "auto" ? "active" : ""}>自动</span></div>
        <button className={listening ? "button danger" : "button secondary"} onClick={toggleDictation}><Mic size={16} />麦克风</button>
        <button className="button secondary" onClick={() => ttsSupported && speak(currentPrompt, "zh-CN")} disabled={!ttsSupported}><Volume2 size={16} />朗读</button>
        <button className="button secondary" onClick={() => setAnswerDraft({ interimText: "", finalText: "", editableText: "", lastFinalAt: 0 })}>重说</button>
        <button className="button primary" onClick={submitAnswer} disabled={!answer.trim() || submitting}><Check size={16} />{submitting ? "追问中" : "我说完了"}</button>
        <button className="button secondary" onClick={() => setPaused((current) => !current)}>{paused ? "继续" : "暂停"}</button>
        <button className="button danger" onClick={finish}>挂断</button>
        <button className="button secondary" onClick={showCueCard}>题词卡</button>
      </footer>
      {backendHint && <div className="room-backend-hint">{backendHint}</div>}
    </section>
  );
}

