import { safeJsonParse } from "./utils";

export interface LlmMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface LlmClient {
  model: string;
  chatJson<T>(messages: LlmMessage[], fallback: T, options?: { temperature?: number; signal?: AbortSignal }): Promise<{ data: T; status: "success" | "fallback"; raw: string }>;
}

const DEEPSEEK_ENDPOINT = "https://api.deepseek.com/chat/completions";

export function createLlmClient(apiKey = process.env.DEEPSEEK_API_KEY ?? ""): LlmClient {
  return {
    model: "deepseek-chat",
    async chatJson<T>(messages: LlmMessage[], fallback: T, options?: { temperature?: number; signal?: AbortSignal }) {
      if (!apiKey) return { data: fallback, status: "fallback", raw: "LLM_NOT_CONFIGURED" };
      try {
        const response = await fetch(DEEPSEEK_ENDPOINT, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${apiKey}`,
          },
          body: JSON.stringify({
            model: "deepseek-chat",
            temperature: options?.temperature ?? 0.35,
            stream: false,
            messages,
          }),
          signal: options?.signal,
        });
        if (!response.ok) return { data: fallback, status: "fallback", raw: await response.text().catch(() => "") };
        const json = (await response.json()) as { choices?: Array<{ message?: { content?: string } }> };
        const content = json.choices?.[0]?.message?.content ?? "";
        const parsed = extractJson<T>(content);
        return parsed ? { data: parsed, status: "success", raw: content } : { data: fallback, status: "fallback", raw: content };
      } catch (error) {
        return { data: fallback, status: "fallback", raw: String(error) };
      }
    },
  };
}

function extractJson<T>(text: string): T | null {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const body = fenced ? fenced[1] : text;
  const objectStart = body.indexOf("{");
  const arrayStart = body.indexOf("[");
  const start = arrayStart !== -1 && (objectStart === -1 || arrayStart < objectStart) ? arrayStart : objectStart;
  if (start < 0) return null;
  const closing = body[start] === "[" ? "]" : "}";
  const end = body.lastIndexOf(closing);
  if (end <= start) return null;
  return safeJsonParse<T>(body.slice(start, end + 1));
}

