  if (!/\d/.test(lastAnswer)) return "刚才这段回答还缺少结果数据。你能补一个最能证明效果的指标吗？";
  if (!/(我|本人|自己|负责|主导|协助)/.test(lastAnswer)) return "你在这段经历里的个人贡献边界是什么？哪些是你直接推动的？";
  const skill = position.job.hardSkills[0] ?? profile.resume.skills[0] ?? "岗位核心能力";
