function mergeEvidence(base: EvidenceItem[], extra: EvidenceItem[]): EvidenceItem[] {
  const seen = new Set<string>();
  return [...base, ...extra].filter((item) => {
    const key = `${item.title}|${item.detail}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function withEvidenceLibrary(profile: CandidateProfile): ResumeAnalysis {
  return {
    ...profile.resume,
    evidence: mergeEvidence(profile.evidenceLibrary, profile.resume.evidence),
  };
}

function pickEvidenceForQuestion(question: string, evidence: EvidenceItem[], jobKeywords: string[]): EvidenceItem[] {
  const signals = unique([...extractKeywords(question, 12), ...jobKeywords.slice(0, 8)]);
  const scored = evidence
    .map((item) => {
      const haystack = `${item.title} ${item.detail} ${item.keywords.join(" ")}`.toLowerCase();
      const score = signals.reduce((sum, signal) => sum + (haystack.includes(signal.toLowerCase()) ? 1 : 0), 0);
      return { item, score };
    })
    .sort((a, b) => b.score - a.score);
  const matched = scored.filter((entry) => entry.score > 0).map((entry) => entry.item);
  return (matched.length > 0 ? matched : evidence).slice(0, 3);
}

