  }
}

function normalizeList(value: unknown, fallback: string[]): string[] {
  return Array.isArray(value) ? value.map((item) => String(item).trim()).filter(Boolean) : fallback;
}

function buildEvidenceTrace(evidenceIds: string[], evidence: Array<{ id: string; title: string; detail: string; impact: string }>): AiRunMeta["evidenceTrace"] {
  return Array.from(new Set(evidenceIds))
    .map((id) => evidence.find((item) => item.id === id))
    .filter(Boolean)
    .slice(0, 4)
    .map((item) => ({
      id: item!.id,
      title: item!.title,
      reason: item!.impact || item!.detail,
    }));
}

