  );
}

export function buildResumeSections(profile: CandidateProfile): Array<{ id: ResumeSectionId; label: string; title: string; content: string; icon: LucideIcon }> {
  const evidenceByType = (type: EvidenceType) =>
    profile.evidenceLibrary.filter((item) => item.type === type).map((item) => `${item.title}\n${item.detail}\n${item.impact}`).join("\n\n");
  return [
    { id: "basic", label: "基本信息", title: profile.displayName || profile.resume.name || "候选人", content: `${profile.resume.name}\n${profile.resume.targetRole}\n${profile.resume.summary}`, icon: UserRound },
    { id: "education", label: "教育经历", title: "教育经历", content: evidenceByType("教育") || profile.resumeText.split(/\n/).filter((line) => /大学|本科|硕士|GPA|教育/.test(line)).join("\n"), icon: GraduationCap },
    { id: "highlights", label: "优势亮点", title: "优势亮点", content: profile.highlights.length ? profile.highlights.join("\n") : generateHighlightsLocal(profile).join("\n"), icon: Check },
    { id: "work", label: "工作经历", title: "工作经历", content: evidenceByType("实习") || profile.evidenceLibrary.slice(0, 2).map((item) => `${item.title}\n${item.detail}`).join("\n\n"), icon: ClipboardList },
    { id: "projects", label: "项目经历", title: "项目经历", content: evidenceByType("项目") || profile.evidenceLibrary.map((item) => `${item.title}\n${item.detail}`).join("\n\n"), icon: Target },
    { id: "skills", label: "技能", title: "技能与工具", content: profile.resume.skills.join("、"), icon: BookOpenCheck },
    { id: "risks", label: "风险", title: "需要补强", content: profile.resume.risks.join("\n"), icon: RefreshCw },
  ];
}

export function sectionsToDrafts(sections: Array<{ id: ResumeSectionId; content: string }>): Record<ResumeSectionId, string> {
  return sections.reduce((acc, section) => ({ ...acc, [section.id]: section.content }), { basic: "", education: "", highlights: "", work: "", projects: "", skills: "", risks: "" });
}

export function resolveEvidenceType(sectionId: ResumeSectionId): EvidenceType {
  if (sectionId === "education") return "教育";
  if (sectionId === "skills") return "技能";
  return "项目";
}

export function buildResumeSuggestion(title: string, content: string, profile: CandidateProfile): string {
  const metrics = profile.resume.metrics.slice(0, 3).join("、") || "可验证指标";
  const skills = profile.resume.skills.slice(0, 5).join("、") || "岗位核心能力";
  const clean = content.replace(/\s+/g, " ").trim();
  return [
    `${title}优化版：`,
    `- 先突出岗位相关结论：具备 ${skills}，能把用户问题拆成可执行方案。`,
    `- 再给真实证据：${clean.slice(0, 180) || profile.evidenceLibrary[0]?.detail || "补充一段最相关经历"}。`,
    `- 最后补量化结果或复盘：用 ${metrics} 说明效果，避免只有职责描述。`,
  ].join("\n");
}

export function MetricCard({ label, value, suffix, detail, icon: Icon }: { label: string; value: string; suffix: string; detail: string; icon: LucideIcon }) {
  return <article className="metric-card"><Icon size={20} /><span>{label}</span><div><strong>{value}</strong><small>{suffix}</small></div><p>{detail}</p></article>;
}

export function Panel({ title, children }: { title: string; children: ReactNode }) {
  return <section className="panel"><header><h2>{title}</h2></header>{children}</section>;
}

export function EmptyState({ title, detail }: { title: string; detail: string }) {
  return <div className="empty-state" role="status"><strong>{title}</strong><p>{detail}</p></div>;
}

export function EditorHeader({ icon: Icon, title, description, action }: { icon: LucideIcon; title: string; description: string; action?: ReactNode }) {
  return <div className="section-header"><div className="header-icon"><Icon size={20} /></div><div><h2>{title}</h2><p>{description}</p></div>{action && <div className="section-action">{action}</div>}</div>;
}

export function profileSummary(resume: ResumeAnalysis) {
  return `${resume.targetRole} · ${resume.skills.slice(0, 5).join(" / ")}`;
}

