import type { AiRunMeta } from "../lib/apiClient";
import type { InterviewConfig, RecognizedDraft, SpeechCaptureState, RealtimeSubmitMode } from "./shared";

export function LiveAssistantDashboard({
  workspace,
  profile,
  position,
  onSaveRecord,
  onSaveQuestion,
  onSubmitJd,
  onMock,
  onContext,
}: {
  workspace: WorkspaceState | null;
  profile: CandidateProfile;
  position: Position;
  onSaveRecord: (payload: { mode: "live"; title: string; transcript: MockMessage[]; cueCards: AnswerCueCard[]; speechMetrics?: ReturnType<typeof analyzeSpeech>[] }) => void;
  onSaveQuestion: (card: AnswerCueCard) => void;
  onSubmitJd: (jobText: string) => void;
  onMock: (config?: InterviewConfig) => void;
  onContext: () => void;
}) {
  const [contextOpen, setContextOpen] = useState(false);
  return (
    <section className="page-section live-dashboard">
      <header className="live-dashboard-hero">
        <div>
          <p className="eyebrow">实时面试助手</p>
          <h1>听到问题，立刻拿到可讲的回答框架</h1>
          <p>JD、简历证据和问题库都只做一件事：在面试中帮你更快组织表达，并把本次记录沉淀到复盘。</p>
        </div>
        <div className="live-hero-actions">
          <button className="button secondary" onClick={() => setContextOpen(true)}>确认 JD</button>
          <button className="button secondary" onClick={onContext}>上下文资料</button>
          <button className="button primary" onClick={() => onMock()}>模拟练习</button>
        </div>
      </header>
      <div className="live-dashboard-grid">
        <LiveAssistantView profile={profile} position={position} onSaveRecord={onSaveRecord} onSaveQuestion={onSaveQuestion} compact />
        <aside className="live-context-rail">
          <section className="context-readiness-card">
            <span>当前岗位</span>
            <strong>{position.title}</strong>
            <p>{position.company} · 匹配 {position.matchReport.score}/100</p>
          </section>
          <section className="context-readiness-card">
            <span>可用素材</span>
            <strong>{profile.evidenceLibrary.length} 条证据</strong>
            <p>{workspace ? `优先练 ${workspace.questions.filter((item) => item.priority).length} 道高优先级问题。` : "先确认 JD 后进入实时助手。"}</p>
          </section>
          <ContextStack profile={profile} position={position} />
        </aside>
      </div>
      {contextOpen && workspace && (
        <div className="modal-backdrop" role="presentation" onClick={() => setContextOpen(false)}>
          <section className="flow-modal" role="dialog" aria-modal="true" aria-label="确认 JD" onClick={(event) => event.stopPropagation()}>
            <header><span>上下文准备</span><button className="button text-button" onClick={() => setContextOpen(false)}>关闭</button></header>
            <h2>确认当前 JD</h2>
            <form onSubmit={(event) => {
              event.preventDefault();
              const form = event.currentTarget;
