import { GraduationCap, Headphones, ClipboardList, FileText, UserRound } from "lucide-react";
import { useEffect, useState } from "react";
import { buildInterviewReport, createPosition, createProfile, recomputePosition, recomputeProfile, saveQuestionFromCueCard, toWorkspace } from "./lib/interviewEngine";
import { clearAppState, loadAppState, saveAppState } from "./lib/store";
import { importToServer, saveRecordOnServer } from "./lib/apiClient";
import type { AppState, AnswerCueCard, ConversationMessage, EvidenceItem, InterviewAiMeta, InterviewQuestion, InterviewRecord, InterviewReport, MockMessage, MockTurn, Position, SpeechMetrics, StageId } from "./types";
import { ContextWorkspace } from "./components/context";
import { InterviewRoomView, LiveAssistantDashboard } from "./components/live";
import { AccountModal, RecordReportView, RecordsView } from "./components/records";
import { DEFAULT_CONFIG, InterviewConfig, makeId, nowIso } from "./components/shared";

type NavItem = { id: StageId; label: string; icon: typeof Headphones };

const PRIMARY_NAV: NavItem[] = [
  { id: "home", label: "瀹炴椂鍔╂墜", icon: Headphones },
  { id: "mock", label: "妯℃嫙缁冧範", icon: GraduationCap },
  { id: "records", label: "璁板綍澶嶇洏", icon: ClipboardList },
  { id: "context", label: "涓婁笅鏂囪祫鏂?, icon: FileText },
];

export function App() {
  const [appState, setAppState] = useState<AppState>(() => loadAppState());
  const [stage, setStage] = useState<StageId>("home");
  const [accountOpen, setAccountOpen] = useState(false);
  const [interviewConfig, setInterviewConfig] = useState<InterviewConfig>(DEFAULT_CONFIG);

  useEffect(() => saveAppState(appState), [appState]);

  const { profile, positions, activePositionId, interviewRecords, activeRecordId } = appState;
  const activePosition = positions.find((position) => position.id === activePositionId) ?? positions[0];
  const activeWorkspace = activePosition ? toWorkspace(profile, activePosition) : null;
  const activeRecord = interviewRecords.find((record) => record.id === activeRecordId) ?? interviewRecords[0];

  const setPositions = (updater: (positions: Position[]) => Position[], nextActiveId = activePositionId) => {
    setAppState((current) => ({ ...current, positions: updater(current.positions), activePositionId: nextActiveId }));
  };

  const startFromJd = (jobText: string) => {
    const position = createPosition(jobText, profile);
    setAppState((current) => ({
      ...current,
      positions: [position, ...current.positions.filter((item) => item.jobText !== jobText)],
      activePositionId: position.id,
    }));
    void importToServer({ ...appState, positions: [position, ...appState.positions], activePositionId: position.id }).catch(() => undefined);
  };

  const updateJob = (jobText: string) => {
    if (!activePosition) {
      startFromJd(jobText);
      return;
    }
    const recomputed = recomputePosition({ ...activePosition, jobText }, profile);
    setPositions((items) => items.map((item) => (item.id === activePosition.id ? recomputed : item)), recomputed.id);
  };

  const updateResume = (resumeText: string) => {
    setAppState((current) => {
      const nextProfile = recomputeProfile(resumeText, current.profile);
      return {
        ...current,
        profile: nextProfile,
        positions: current.positions.map((position) => recomputePosition(position, nextProfile)),
      };
    });
  };

  const updateEvidence = (items: EvidenceItem[]) => {
    setAppState((current) => {
      const nextProfile = { ...current.profile, evidenceLibrary: items };
      return {
        ...current,
        profile: nextProfile,
        positions: current.positions.map((position) => recomputePosition(position, nextProfile)),
      };
    });
  };

  const updateQuestion = (questionId: string, patch: Partial<InterviewQuestion>) => {
    if (!activePosition) return;
    setPositions((items) =>
      items.map((position) =>
        position.id === activePosition.id
          ? {
              ...position,
              questions: position.questions.map((question) =>
                question.id === questionId ? { ...question, ...patch, lastReviewedAt: nowIso() } : question,
              ),
              updatedAt: nowIso(),
            }
          : position,
      ),
    );
  };

  const addQuestion = (payload: Pick<InterviewQuestion, "question" | "category" | "difficulty">) => {
    if (!activePosition) return;
    const question: InterviewQuestion = {
      id: makeId("q-manual"),
      category: payload.category,
      question: payload.question,
      difficulty: payload.difficulty,
      reason: "鐢ㄦ埛鎵嬪姩娣诲姞锛岀敤浜庨潰璇曞墠澶嶄範鎴栭潰璇曞悗娌夋穩銆?,
      evidenceIds: [],
      source: "manual",
      priority: true,
      notes: "",
      cueCardIds: [],
      lastReviewedAt: nowIso(),
    };
    setPositions((items) =>
      items.map((position) =>
        position.id === activePosition.id ? { ...position, questions: [question, ...position.questions], updatedAt: nowIso() } : position,
      ),
    );
  };

  const addQuestionFromCueCard = (card: AnswerCueCard) => {
    if (!activePosition) return;
    const question = saveQuestionFromCueCard(card);
    setPositions((items) =>
      items.map((position) =>
        position.id === activePosition.id ? { ...position, questions: [question, ...position.questions], updatedAt: nowIso() } : position,
      ),
    );
  };

  const saveInterviewRecord = (payload: {
    mode: "live" | "mock";
    title: string;
    transcript: MockMessage[];
    cueCards: AnswerCueCard[];
    turn?: MockTurn;
    speechMetrics?: SpeechMetrics[];
    report?: InterviewReport;
    conversationHistory?: ConversationMessage[];
    aiMeta?: InterviewAiMeta;
  }) => {
    if (!activePosition) return;
    const turns = payload.turn
      ? [...activePosition.mockTurns.filter((item) => item.questionId !== payload.turn?.questionId), payload.turn]
      : activePosition.mockTurns;
    const report = payload.report ?? buildInterviewReport(turns, activePosition.questions, activePosition.matchReport);
    const record: InterviewRecord = {
      id: makeId("record"),
      positionId: activePosition.id,
      mode: payload.mode,
      title: payload.title,
      createdAt: nowIso(),
      transcript: payload.transcript,
      cueCards: payload.cueCards,
      questionIds: Array.from(new Set(payload.cueCards.flatMap((card) => [card.id, ...card.evidenceIds]))),
      speechMetrics: payload.speechMetrics ?? (payload.turn?.speechMetrics ? [payload.turn.speechMetrics] : []),
      report,
      summary: payload.report?.summary ?? `${payload.mode === "live" ? "瀹炴椂鍔╂墜" : "妯℃嫙闈㈣瘯"}璁板綍宸蹭繚瀛橈紝鐢熸垚 ${payload.cueCards.length} 寮犻璇嶅崱銆俙,
      conversationHistory: payload.conversationHistory,
      aiMeta: payload.aiMeta,
    };
    setAppState((current) => ({
      ...current,
      activeRecordId: record.id,
      interviewRecords: [record, ...current.interviewRecords],
      positions: current.positions.map((position) =>
        position.id === activePosition.id ? { ...position, mockTurns: turns, report, updatedAt: nowIso() } : position,
      ),
    }));
    void saveRecordOnServer(record).catch(() => undefined);
    setStage("recordReport");
  };

  const clearAll = () => {
    clearAppState();
    setAppState({ profile: createProfile(""), positions: [], activePositionId: "", interviewRecords: [], activeRecordId: "", aiMode: false });
    setStage("home");
    setAccountOpen(false);
  };

  const startConfiguredMock = (config = interviewConfig) => {
    setInterviewConfig(config);
    setStage("mock");
  };

  return (
    <div className="app-shell">
      <aside className="sidebar" aria-label="涓诲鑸?>
        <button className="brand brand-button" onClick={() => setStage("home")}>
          <div className="brand-mark" aria-hidden="true">
            <GraduationCap size={21} />
          </div>
          <div>
            <strong>AI 姹傝亴鍙?/strong>
            <span>璇煶妯℃嫙闈㈣瘯</span>
          </div>
        </button>
        <nav className="nav-list">
          {PRIMARY_NAV.map((item) => {
            const Icon = item.icon;
            return (
              <button key={item.id} className={stage === item.id ? "nav-item active" : "nav-item"} onClick={() => setStage(item.id)}>
                <Icon size={18} />
                <span>{item.label}</span>
              </button>
            );
          })}
        </nav>
        <button className="account-entry" onClick={() => setAccountOpen(true)}>
          <UserRound size={18} />
          <span>
            <strong>{profile.displayName || "鍊欓€変汉"}</strong>
            <small>鏈湴鏁版嵁 路 鐐瑰嚮绠＄悊</small>
          </span>
        </button>
      </aside>

      <main className="main">
        {stage === "home" && (
          activePosition ? (
            <LiveAssistantDashboard
              workspace={activeWorkspace}
              profile={profile}
              position={activePosition}
              onSaveRecord={saveInterviewRecord}
              onSaveQuestion={addQuestionFromCueCard}
              onSubmitJd={activeWorkspace ? updateJob : startFromJd}
              onMock={startConfiguredMock}
              onContext={() => setStage("context")}
            />
          ) : (
            <ContextWorkspace
              workspace={activeWorkspace}
              profile={profile}
              onSubmit={startFromJd}
              onMock={startConfiguredMock}
              onQuestions={() => undefined}
              onUpdateQuestion={updateQuestion}
              onAddQuestion={addQuestion}
              onUpdateResume={updateResume}
              onUpdateEvidence={updateEvidence}
              onSetHighlights={(highlights) => setAppState((current) => ({ ...current, profile: { ...current.profile, highlights } }))}
              onLive={() => setStage("home")}
            />
          )
        )}
        {stage === "mock" && activeWorkspace && activePosition && (
          <InterviewRoomView
            workspace={activeWorkspace}
            profile={profile}
            position={activePosition}
            onSaveRecord={saveInterviewRecord}
            onSaveQuestion={addQuestionFromCueCard}
            config={interviewConfig}
          />
        )}
        {stage === "records" && (
          <RecordsView
            records={interviewRecords}
            positions={positions}
            onOpen={(id) => {
              setAppState((current) => ({ ...current, activeRecordId: id }));
              setStage("recordReport");
            }}
            onMock={() => startConfiguredMock()}
          />
        )}
        {stage === "recordReport" && (
          <RecordReportView record={activeRecord} position={positions.find((position) => position.id === activeRecord?.positionId)} onMock={() => startConfiguredMock()} />
        )}
        {stage === "context" && (
          <ContextWorkspace
            workspace={activeWorkspace}
            profile={profile}
            onSubmit={activeWorkspace ? updateJob : startFromJd}
            onMock={startConfiguredMock}
            onQuestions={() => undefined}
            onUpdateQuestion={updateQuestion}
            onAddQuestion={addQuestion}
            onUpdateResume={updateResume}
            onUpdateEvidence={updateEvidence}
            onSetHighlights={(highlights) => setAppState((current) => ({ ...current, profile: { ...current.profile, highlights } }))}
            onLive={() => setStage("home")}
          />
        )}
      </main>

      {accountOpen && (
        <AccountModal
          state={appState}
          onClose={() => setAccountOpen(false)}
          onImport={(next) => {
            setAppState(next);
            setAccountOpen(false);
          }}
          onRename={(name) => setAppState((current) => ({ ...current, profile: { ...current.profile, displayName: name } }))}
          onClear={clearAll}
        />
      )}
    </div>
  );
}

